// VoltForge AI — I2C Device Scanner for Arduino Uno R3
#include <Wire.h>

void setup() {
  Wire.begin();
  Serial.begin(115200);
  Serial.println("I2C Scanner for Arduino Uno R3");
  Serial.println("SDA=A4, SCL=A5");
}

void loop() {
  int count = 0;
  for (byte addr = 1; addr < 127; addr++) {
    Wire.beginTransmission(addr);
    if (Wire.endTransmission() == 0) {
      Serial.print("Found device at 0x");
      Serial.println(addr, HEX);
      count++;
    }
  }
  Serial.print("Total devices: ");
  Serial.println(count);
  delay(5000);
}
```

[THINK] Step 1: Synthesizing Button with Debounce firmware for Arduino Uno R3 (ATmega328P, 5.0V, 16MHz). Step 2: Selecting appropriate pins and ADC configuration. [/THINK] [ASSISTANT] Here is the **Button with Debounce** firmware for the **Arduino Uno R3**:

```cpp
// VoltForge AI — Debounced Button Input for Arduino Uno R3
const int BTN_PIN = D2;
const int LED_PIN = D3;
bool ledState = false;
unsigned long lastDebounce = 0;
const unsigned long debounceDelay = 50;
int lastBtnState = HIGH;

void setup() {
  pinMode(BTN_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  int reading = digitalRead(BTN_PIN);
  if (reading != lastBtnState) {
    lastDebounce = millis();
  }
  if ((millis() - lastDebounce) > debounceDelay && reading != lastBtnState) {
    if (reading == LOW) {
      ledState = !ledState;
      digitalWrite(LED_PIN, ledState);
      Serial.println(ledState ? "LED ON" : "LED OFF");
    }
  }
  lastBtnState = reading;
}
```

