```cpp
// VoltForge AI — Multi-Sensor Data Logger for Arduino Uno R3
const int SENSOR_A = A0;
const int SENSOR_B = A1;
unsigned long logInterval = 1000;
unsigned long lastLog = 0;
unsigned long sampleCount = 0;

void setup() {
  Serial.begin(115200);
  Serial.println("Timestamp,SensorA,SensorB,Voltage_A");
}

void loop() {
  if (millis() - lastLog >= logInterval) {
    lastLog = millis();
    int a = analogRead(SENSOR_A);
    int b = analogRead(SENSOR_B);
    float va = (a * 5.0) / 1023.0;
    Serial.print(millis()); Serial.print(",");
    Serial.print(a); Serial.print(",");
    Serial.print(b); Serial.print(",");
    Serial.println(va, 3);
    sampleCount++;
  }
}
```

